// AIServiceServer is the server API for AIService service.
// All implementations should embed UnimplementedAIServiceServer
// for forward compatibility.
//
// AIService manages workspace AI settings, LLM providers, model registry,
// unified MCP servers, autonomous agents, private streaming chat threads,
// headless text/structured generation, and execution observability.
type AIServiceServer interface {
	// Retrieves workspace AI settings including model role defaults, governance, and current monthly spend.
	GetSettings(context.Context, *GetSettingsRequest) (*Settings, error)
	// Updates workspace AI settings using a field mask.
	UpdateSettings(context.Context, *UpdateSettingsRequest) (*Settings, error)
	// Lists supported LLM provider driver descriptors and defaults.
	ListProviderDescriptors(context.Context, *ListProviderDescriptorsRequest) (*ListProviderDescriptorsResponse, error)
	// Lists all configured LLM providers in the workspace.
	ListProviders(context.Context, *ListProvidersRequest) (*ListProvidersResponse, error)
	// Retrieves a single LLM provider configuration (secrets masked).
	GetProvider(context.Context, *GetProviderRequest) (*Provider, error)
	// Creates a new LLM provider connection and auto-seeds curated default models.
	CreateProvider(context.Context, *CreateProviderRequest) (*Provider, error)
	// Updates an existing LLM provider configuration or rotates its secret using a field mask.
	UpdateProvider(context.Context, *UpdateProviderRequest) (*Provider, error)
	// Deletes an LLM provider connection and its associated models.
	DeleteProvider(context.Context, *DeleteProviderRequest) (*emptypb.Empty, error)
	// Verifies connectivity and credentials for an LLM provider and updates its status.
	TestProvider(context.Context, *TestProviderRequest) (*Provider, error)
	// Discovers available upstream models for an LLM provider.
	DiscoverProviderModels(context.Context, *DiscoverProviderModelsRequest) (*DiscoverProviderModelsResponse, error)
	// Synchronizes upstream catalog or discovered models into the workspace model registry.
	SyncProviderModels(context.Context, *SyncProviderModelsRequest) (*SyncProviderModelsResponse, error)
	// Lists registered AI models in the workspace.
	ListModels(context.Context, *ListModelsRequest) (*ListModelsResponse, error)
	// Retrieves a single registered AI model.
	GetModel(context.Context, *GetModelRequest) (*Model, error)
	// Registers a custom or catalog AI model under a workspace provider.
	CreateModel(context.Context, *CreateModelRequest) (*Model, error)
	// Updates a registered AI model's display name, profile, config, or enabled state.
	UpdateModel(context.Context, *UpdateModelRequest) (*Model, error)
	// Deletes a registered AI model from the workspace.
	DeleteModel(context.Context, *DeleteModelRequest) (*emptypb.Empty, error)
	// Lists unified MCP servers (including the lazily seeded built-in Saturn Workspace MCP).
	ListMCPServers(context.Context, *ListMCPServersRequest) (*ListMCPServersResponse, error)
	// Retrieves a single MCP server configuration and live discovery state.
	GetMCPServer(context.Context, *GetMCPServerRequest) (*MCPServer, error)
	// Registers a remote HTTP MCP server in the workspace.
	CreateMCPServer(context.Context, *CreateMCPServerRequest) (*MCPServer, error)
	// Updates an MCP server configuration or auth secret using a field mask.
	UpdateMCPServer(context.Context, *UpdateMCPServerRequest) (*MCPServer, error)
	// Deletes a user-configured MCP server. System MCP servers cannot be deleted.
	DeleteMCPServer(context.Context, *DeleteMCPServerRequest) (*emptypb.Empty, error)
	// Tests connectivity to an MCP server and updates its discovery health status.
	TestMCPServer(context.Context, *TestMCPServerRequest) (*MCPServer, error)
	// Synchronizes tools and server metadata from an MCP server.
	SyncMCPServer(context.Context, *SyncMCPServerRequest) (*MCPServer, error)
	// Lists AI agents in the workspace (lazily seeding the built-in Saturn Assistant).
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// Retrieves a single AI agent by ID or system key.
	GetAgent(context.Context, *GetAgentRequest) (*Agent, error)
	// Creates a custom AI agent with optional MCP server bindings and output schema.
	CreateAgent(context.Context, *CreateAgentRequest) (*Agent, error)
	// Updates an existing AI agent configuration using a field mask.
	UpdateAgent(context.Context, *UpdateAgentRequest) (*Agent, error)
	// Deletes a user-created AI agent. Built-in system agents cannot be deleted.
	DeleteAgent(context.Context, *DeleteAgentRequest) (*emptypb.Empty, error)
	// Resets a built-in system agent back to its factory blueprint defaults.
	ResetAgent(context.Context, *ResetAgentRequest) (*Agent, error)
	// Executes an agent headlessly in a multi-step MCP-enabled run.
	ExecuteAgent(context.Context, *ExecuteAgentRequest) (*Run, error)
	// Lists private chat threads belonging to the authenticated user in the workspace.
	ListThreads(context.Context, *ListThreadsRequest) (*ListThreadsResponse, error)
	// Retrieves a private chat thread owned by the authenticated user.
	GetThread(context.Context, *GetThreadRequest) (*Thread, error)
	// Creates a new private chat thread (lazily seeding system AI defaults if needed).
	CreateThread(context.Context, *CreateThreadRequest) (*Thread, error)
	// Updates a private chat thread (title, agent, model, pin/archive, config) using a field mask.
	UpdateThread(context.Context, *UpdateThreadRequest) (*Thread, error)
	// Deletes a private chat thread and all of its messages.
	DeleteThread(context.Context, *DeleteThreadRequest) (*emptypb.Empty, error)
	// Lists persisted messages in a private chat thread ordered by sequence number.
	ListThreadMessages(context.Context, *ListThreadMessagesRequest) (*ListThreadMessagesResponse, error)
	// Cancels an active streaming turn on a private chat thread.
	CancelThreadTurn(context.Context, *CancelThreadTurnRequest) (*Thread, error)
	// Streams a new conversational turn on a private thread over gRPC server streaming.
	StreamThreadTurn(*StreamThreadTurnRequest, grpc.ServerStreamingServer[ThreadStreamEvent]) error
	// Resolves pending write-tool approval requests and resumes streaming the thread turn.
	StreamResolveToolApprovals(*StreamResolveToolApprovalsRequest, grpc.ServerStreamingServer[ThreadStreamEvent]) error
	// Executes a single-turn headless generation with optional attachments and output schema.
	Generate(context.Context, *GenerateRequest) (*Run, error)
	// Lists AI execution runs across chat, workflow, API, and MCP sources.
	ListRuns(context.Context, *ListRunsRequest) (*ListRunsResponse, error)
	// Retrieves a single AI execution run hydrated with its ordered LLM/tool steps.
	GetRun(context.Context, *GetRunRequest) (*Run, error)
}

